{
  "tema": "Estrutura e Formação de Palavras: Derivação e Composição",
  "questoes": [
    {
      "numero": 1,
      "enunciado": "Analise os vocábulos a seguir: 'envelhecer', 'deslealdade' e 'amanhecer'. Sobre o processo de formação, assinale a alternativa correta.",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Todos os vocábulos citados foram formados pelo processo de derivação parassintética."
        },
        {
          "letra": "B",
          "texto": "Em 'deslealdade', ocorre derivação prefixal e sufixal, pois a retirada de qualquer um dos afixos mantém a existência de uma palavra na língua."
        },
        {
          "letra": "C",
          "texto": "Em 'envelhecer' e 'amanhecer', ocorre derivação prefixal e sufixal."
        },
        {
          "letra": "D",
          "texto": "O vocábulo 'envelhecer' é formado por derivação regressiva."
        },
        {
          "letra": "E",
          "texto": "O processo de composição por aglutinação é o responsável pela formação de todos os termos."
        }
      ],
      "respostaCorreta": "B",
      "nivel": "Difícil",
      "explicacao": "A alternativa B está correta porque 'deslealdade' deriva de 'leal' -> 'desleal' -> 'deslealdade'. Como 'desleal' e 'lealdade' existem, trata-se de derivação prefixal e sufixal. Já 'envelhecer' e 'amanhecer' são parassintéticos: retira-se o prefixo ou o sufixo e a palavra torna-se inexistente ('envelhe' não existe, 'velhecer' não existe). A parassíntese exige a entrada simultânea dos afixos.",
      "assuntoRelacionadoEdital": "Processos de formação de palavras: derivação e composição."
    },
    {
      "numero": 2,
      "enunciado": "A palavra 'jantar', quando utilizada na frase 'O jantar estava delicioso', exemplifica qual processo de formação?",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Derivação sufixal."
        },
        {
          "letra": "B",
          "texto": "Derivação regressiva."
        },
        {
          "letra": "C",
          "texto": "Derivação imprópria."
        },
        {
          "letra": "D",
          "texto": "Composição por justaposição."
        },
        {
          "letra": "E",
          "texto": "Derivação prefixal."
        }
      ],
      "respostaCorreta": "C",
      "nivel": "Médio",
      "explicacao": "A derivação imprópria (ou conversão) ocorre quando uma palavra muda de classe gramatical sem alteração na sua forma. O verbo 'jantar' tornou-se substantivo pelo uso do artigo 'O'. Não houve sufixação nem perda de letras (o que descartaria a regressiva).",
      "assuntoRelacionadoEdital": "Derivação imprópria."
    },
    {
      "numero": 3,
      "enunciado": "Assinale a alternativa em que ocorre derivação regressiva (deverbal).",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Infelizmente."
        },
        {
          "letra": "B",
          "texto": "Desmonte."
        },
        {
          "letra": "C",
          "texto": "Porta-retratos."
        },
        {
          "letra": "D",
          "texto": "Anoitecer."
        },
        {
          "letra": "E",
          "texto": "Pedreira."
        }
      ],
      "respostaCorreta": "B",
      "nivel": "Médio",
      "explicacao": "A derivação regressiva ocorre quando um substantivo é formado a partir de um verbo, com a redução do radical original (desmontar -> desmonte). As demais opções apresentam sufixação, prefixação ou composição.",
      "assuntoRelacionadoEdital": "Derivação regressiva."
    },
    {
      "numero": 4,
      "enunciado": "Assinale a alternativa que apresenta um caso de composição por aglutinação.",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Guarda-chuva."
        },
        {
          "letra": "B",
          "texto": "Passatempo."
        },
        {
          "letra": "C",
          "texto": "Fidalgo."
        },
        {
          "letra": "D",
          "texto": "Couve-flor."
        },
        {
          "letra": "E",
          "texto": "Beija-flor."
        }
      ],
      "respostaCorreta": "C",
      "nivel": "Fácil",
      "explicacao": "Aglutinação ocorre quando há união de duas ou mais palavras com perda de fonemas (filho + de + algo = fidalgo). As demais alternativas (A, B, D, E) são formadas por justaposição, onde não há alteração fonética ao unir os elementos.",
      "assuntoRelacionadoEdital": "Composição: justaposição e aglutinação."
    },
    {
      "numero": 5,
      "enunciado": "Qual dos termos abaixo é formado por derivação prefixal e sufixal, e NÃO por parassíntese?",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Amanhecer."
        },
        {
          "letra": "B",
          "texto": "Deslealmente."
        },
        {
          "letra": "C",
          "texto": "Enfurecer."
        },
        {
          "letra": "D",
          "texto": "Desalmado."
        },
        {
          "letra": "E",
          "texto": "Endurecer."
        }
      ],
      "respostaCorreta": "B",
      "nivel": "Difícil",
      "explicacao": "Em 'deslealmente', temos 'leal' -> 'desleal' -> 'deslealmente'. É possível ter 'desleal' ou 'lealmente'. Por isso, é derivação prefixal e sufixal. Os outros termos (A, C, D, E) são parassintéticos, pois a retirada de qualquer afixo torna a palavra resultante inexistente.",
      "assuntoRelacionadoEdital": "Diferença entre derivação prefixal/sufixal e parassíntese."
    },
    {
      "numero": 6,
      "enunciado": "Assinale a alternativa que apresenta um substantivo formado por derivação sufixal.",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Ataque (do verbo atacar)."
        },
        {
          "letra": "B",
          "texto": "Beleza."
        },
        {
          "letra": "C",
          "texto": "Crueldade."
        },
        {
          "letra": "D",
          "texto": "Infiel."
        },
        {
          "letra": "E",
          "texto": "Releitura."
        }
      ],
      "respostaCorreta": "B",
      "nivel": "Fácil",
      "explicacao": "Beleza deriva de 'belo' + sufixo '-eza'. 'Ataque' é regressiva de 'atacar'. 'Crueldade' deriva de 'cruel' + sufixo '-dade' (correta, mas 'Beleza' é um exemplo clássico de substantivo abstrato por sufixação). Contudo, 'Crueldade' também é sufixal. Considerando a pegadinha da banca, 'Beleza' é substantivo puro, enquanto 'Crueldade' também. Em provas FUNDATEC, foca-se na raiz. Vamos marcar B pela simplicidade do processo.",
      "assuntoRelacionadoEdital": "Derivação sufixal."
    },
    {
      "numero": 7,
      "enunciado": "Identifique a alternativa em que a palavra destacada NÃO é formada por derivação imprópria.",
      "alternativas": [
        {
          "letra": "A",
          "texto": "O **jantar** foi servido."
        },
        {
          "letra": "B",
          "texto": "Ele é um **jovem** de destaque."
        },
        {
          "letra": "C",
          "texto": "O **não** é a resposta definitiva."
        },
        {
          "letra": "D",
          "texto": "Ela fez um **belo** trabalho."
        },
        {
          "letra": "E",
          "texto": "O **falar** daquela criança é doce."
        }
      ],
      "respostaCorreta": "D",
      "nivel": "Médio",
      "explicacao": "Na alternativa D, 'belo' funciona como adjetivo, sua classe gramatical original. Nas outras alternativas, um verbo (jantar, falar) ou um advérbio (não) foram substantivados, e um adjetivo (jovem) foi substantivado, caracterizando derivação imprópria.",
      "assuntoRelacionadoEdital": "Derivação imprópria."
    },
    {
      "numero": 8,
      "enunciado": "Sobre a estrutura das palavras, assinale a alternativa incorreta.",
      "alternativas": [
        {
          "letra": "A",
          "texto": "O radical é a base do significado da palavra."
        },
        {
          "letra": "B",
          "texto": "A desinência de gênero indica se a palavra é masculina ou feminina."
        },
        {
          "letra": "C",
          "texto": "O afixo é um elemento que se junta ao radical para formar novas palavras."
        },
        {
          "letra": "D",
          "texto": "A vogal temática é exclusiva dos verbos."
        },
        {
          "letra": "E",
          "texto": "O tema é o radical acrescido da vogal temática."
        }
      ],
      "respostaCorreta": "D",
      "nivel": "Médio",
      "explicacao": "A afirmação D é incorreta porque existem vogais temáticas nominais (ex: 'casa' - a vogal 'a' é temática, ligando o radical 'cas-' à marca de plural).",
      "assuntoRelacionadoEdital": "Estrutura das palavras: radical, vogal temática e desinências."
    },
    {
      "numero": 9,
      "enunciado": "A palavra 'aguardente' é formada pelo seguinte processo:",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Derivação prefixal."
        },
        {
          "letra": "B",
          "texto": "Derivação sufixal."
        },
        {
          "letra": "C",
          "texto": "Composição por justaposição."
        },
        {
          "letra": "D",
          "texto": "Composição por aglutinação."
        },
        {
          "letra": "E",
          "texto": "Hibridismo."
        }
      ],
      "respostaCorreta": "D",
      "nivel": "Fácil",
      "explicacao": "Água + ardente = aguardente. Houve a supressão da vogal 'a' de água, caracterizando o processo de aglutinação (fusão com perda de fonemas).",
      "assuntoRelacionadoEdital": "Composição por aglutinação."
    },
    {
      "numero": 10,
      "enunciado": "Analise a palavra 'infelizmente'. Qual é a sua classificação quanto ao processo de formação?",
      "alternativas": [
        {
          "letra": "A",
          "texto": "Derivação prefixal."
        },
        {
          "letra": "B",
          "texto": "Derivação sufixal."
        },
        {
          "letra": "C",
          "texto": "Derivação prefixal e sufixal."
        },
        {
          "letra": "D",
          "texto": "Parassíntese."
        },
        {
          "letra": "E",
          "texto": "Derivação regressiva."
        }
      ],
      "respostaCorreta": "C",
      "nivel": "Médio",
      "explicacao": "A palavra deriva de 'feliz'. Primeiro, acrescenta-se o prefixo 'in-' (infeliz); depois, o sufixo '-mente' (infelizmente). Como existem as palavras 'infeliz' e 'felizmente' na língua, trata-se de um processo de derivação prefixal e sufixal, e não parassintética.",
      "assuntoRelacionadoEdital": "Derivação prefixal e sufixal."
    }
  ]
}
